FILES = {
    "app/household_import_models.py": 'from __future__ import annotations\n\nfrom datetime import datetime\n\nfrom sqlalchemy import DateTime, ForeignKey, Integer, String, Text\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.database import Base\n\n\nclass HouseholdImportJob(Base):\n    """Một lần tiếp nhận file cập nhật dữ liệu hộ dân."""\n\n    __tablename__ = "survey_household_import_jobs"\n\n    id: Mapped[int] = mapped_column(\n        Integer,\n        primary_key=True,\n        autoincrement=True,\n    )\n    job_code: Mapped[str] = mapped_column(\n        String(80),\n        unique=True,\n        nullable=False,\n        index=True,\n    )\n    survey_batch_id: Mapped[int] = mapped_column(\n        ForeignKey("survey_batches.id"),\n        nullable=False,\n        index=True,\n    )\n    school_year_id: Mapped[int] = mapped_column(\n        ForeignKey("school_years.id"),\n        nullable=False,\n        index=True,\n    )\n    commune_id: Mapped[int] = mapped_column(\n        ForeignKey("communes.id"),\n        nullable=False,\n        index=True,\n    )\n    uploaded_by_user_id: Mapped[int | None] = mapped_column(\n        ForeignKey("users.id"),\n        nullable=True,\n        index=True,\n    )\n    actor_name_snapshot: Mapped[str | None] = mapped_column(\n        String(200),\n        nullable=True,\n    )\n    actor_role_snapshot: Mapped[str | None] = mapped_column(\n        String(100),\n        nullable=True,\n    )\n    actor_unit_snapshot: Mapped[str | None] = mapped_column(\n        String(300),\n        nullable=True,\n    )\n    original_file_name: Mapped[str] = mapped_column(\n        String(500),\n        nullable=False,\n    )\n    stored_path: Mapped[str | None] = mapped_column(\n        Text,\n        nullable=True,\n    )\n    file_ext: Mapped[str | None] = mapped_column(\n        String(20),\n        nullable=True,\n        index=True,\n    )\n    file_size: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    sha256: Mapped[str | None] = mapped_column(\n        String(64),\n        nullable=True,\n        index=True,\n    )\n    status: Mapped[str] = mapped_column(\n        String(50),\n        default="DA_NHAN",\n        nullable=False,\n        index=True,\n    )\n    stage: Mapped[str | None] = mapped_column(\n        String(50),\n        nullable=True,\n        index=True,\n    )\n    message: Mapped[str | None] = mapped_column(\n        Text,\n        nullable=True,\n    )\n    sheet_names: Mapped[str | None] = mapped_column(\n        Text,\n        nullable=True,\n    )\n    has_macro: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    rows_total: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    rows_valid: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    rows_error: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    conflict_count: Mapped[int] = mapped_column(\n        Integer,\n        default=0,\n        nullable=False,\n    )\n    duplicate_of_job_code: Mapped[str | None] = mapped_column(\n        String(80),\n        nullable=True,\n    )\n    received_at: Mapped[datetime | None] = mapped_column(\n        DateTime,\n        nullable=True,\n    )\n    checked_at: Mapped[datetime | None] = mapped_column(\n        DateTime,\n        nullable=True,\n    )\n    processed_at: Mapped[datetime | None] = mapped_column(\n        DateTime,\n        nullable=True,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime,\n        default=datetime.now,\n        nullable=False,\n        index=True,\n    )\n    updated_at: Mapped[datetime] = mapped_column(\n        DateTime,\n        default=datetime.now,\n        onupdate=datetime.now,\n        nullable=False,\n    )\n\n\nclass HouseholdImportError(Base):\n    """Chi tiết lỗi/khuyến cáo của từng lần gửi file."""\n\n    __tablename__ = "survey_household_import_errors"\n\n    id: Mapped[int] = mapped_column(\n        Integer,\n        primary_key=True,\n        autoincrement=True,\n    )\n    job_id: Mapped[int] = mapped_column(\n        ForeignKey("survey_household_import_jobs.id"),\n        nullable=False,\n        index=True,\n    )\n    severity: Mapped[str] = mapped_column(\n        String(20),\n        default="ERROR",\n        nullable=False,\n        index=True,\n    )\n    sheet_name: Mapped[str | None] = mapped_column(\n        String(300),\n        nullable=True,\n    )\n    row_number: Mapped[int | None] = mapped_column(\n        Integer,\n        nullable=True,\n    )\n    column_name: Mapped[str | None] = mapped_column(\n        String(300),\n        nullable=True,\n    )\n    error_code: Mapped[str | None] = mapped_column(\n        String(80),\n        nullable=True,\n        index=True,\n    )\n    message: Mapped[str] = mapped_column(\n        Text,\n        nullable=False,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime,\n        default=datetime.now,\n        nullable=False,\n    )\n',
    "app/routers/household_updates.py": 'from __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nimport zipfile\nfrom datetime import date, datetime\nfrom io import BytesIO\nfrom pathlib import Path\nfrom uuid import uuid4\nfrom xml.etree import ElementTree\n\nfrom fastapi import APIRouter, Depends, File, Request, UploadFile\nfrom fastapi.responses import FileResponse, HTMLResponse, JSONResponse, RedirectResponse\nfrom fastapi.templating import Jinja2Templates\nfrom sqlalchemy import select, text\nfrom sqlalchemy.orm import Session, selectinload\n\nfrom app.database import get_db\nfrom app.household_import_models import HouseholdImportError, HouseholdImportJob\nfrom app.models import Classroom, School, SchoolYear\nfrom app.permissions import (\n    ADMIN_ROLE_CODES,\n    COMMUNE_ROLE_CODE,\n    DEPARTMENT_ROLE_CODE,\n    SCHOOL_ROLE_CODE,\n    TEACHER_ROLE_CODE,\n    normalize_role_code,\n)\nfrom app.survey_models import (\n    Household,\n    SurveyBatch,\n    SurveyForm,\n    SurveyPerson,\n    SurveyPersonYearRecord,\n)\nfrom app.routers.surveys import (\n    BATCH_STATUS_LABELS,\n    FORM_STATUS_LABELS,\n    LEARNING_STATUS_LABELS,\n    RESIDENCY_STATUS_LABELS,\n    lay_thong_tin_nguoi_dung,\n    tao_bo_loc_bao_cao_theo_nguoi_dung,\n    tao_bo_loc_dot_theo_nguoi_dung,\n)\n\n\nAPP_DIR = Path(__file__).resolve().parent.parent\nPROJECT_DIR = APP_DIR.parent\nREFERENCE_DIR = APP_DIR / "reference" / "bai_13b_9"\nIMPORT_ROOT = PROJECT_DIR / "exports" / "household_imports"\n\ntemplates = Jinja2Templates(directory=str(APP_DIR / "templates"))\n\nrouter = APIRouter(\n    prefix="/dieu-tra",\n    tags=["Cập nhật dữ liệu hộ dân"],\n)\n\nUPLOAD_ROLE_CODES = frozenset(\n    {\n        *ADMIN_ROLE_CODES,\n        COMMUNE_ROLE_CODE,\n        SCHOOL_ROLE_CODE,\n    }\n)\n\nVIEW_ROLE_CODES = frozenset(\n    {\n        *ADMIN_ROLE_CODES,\n        DEPARTMENT_ROLE_CODE,\n        COMMUNE_ROLE_CODE,\n        SCHOOL_ROLE_CODE,\n    }\n)\n\nIMPORT_STATUS_LABELS = {\n    "DA_NHAN": "Đã nhận file",\n    "DANG_KIEM_TRA": "Đang kiểm tra",\n    "DA_KIEM_TRA_CAU_TRUC": "Đã kiểm tra cấu trúc",\n    "CHO_XU_LY_XLS": "Đã nhận – chờ xử lý XLS",\n    "TRUNG_FILE": "File đã gửi trước đó",\n    "LOI_DINH_DANG": "Có lỗi định dạng",\n    "LOI_FILE": "Có lỗi file",\n    "LOI_DOT_KHOA": "Đợt không nhận cập nhật",\n    "DA_CAP_NHAT": "Đã cập nhật thành công",\n    "CO_XUNG_DOT": "Có xung đột dữ liệu",\n}\n\nIMPORT_STATUS_CLASSES = {\n    "DA_NHAN": "info",\n    "DANG_KIEM_TRA": "info",\n    "DA_KIEM_TRA_CAU_TRUC": "success",\n    "CHO_XU_LY_XLS": "warning",\n    "TRUNG_FILE": "warning",\n    "LOI_DINH_DANG": "danger",\n    "LOI_FILE": "danger",\n    "LOI_DOT_KHOA": "danger",\n    "DA_CAP_NHAT": "success",\n    "CO_XUNG_DOT": "warning",\n}\n\n\ndef _user(request: Request) -> dict:\n    return dict(request.scope.get("auth_user") or {})\n\n\ndef _role(request: Request) -> str:\n    return normalize_role_code(_user(request).get("role_code"))\n\n\ndef _scope_label(request: Request) -> str:\n    role_code = _role(request)\n    if role_code == COMMUNE_ROLE_CODE:\n        return "PHẠM VI XÃ/PHƯỜNG"\n    if role_code == SCHOOL_ROLE_CODE:\n        return "PHẠM VI TRƯỜNG ĐƯỢC PHÂN CÔNG"\n    if role_code == DEPARTMENT_ROLE_CODE:\n        return "PHẠM VI TOÀN TỈNH – CHỈ XEM"\n    return "PHẠM VI TOÀN TỈNH"\n\n\ndef _batch_in_scope(\n    db: Session,\n    request: Request,\n    batch_id: int,\n) -> SurveyBatch | None:\n    filters = tao_bo_loc_dot_theo_nguoi_dung(request)\n    return db.scalar(\n        select(SurveyBatch)\n        .options(\n            selectinload(SurveyBatch.school_year),\n            selectinload(SurveyBatch.commune),\n        )\n        .where(\n            SurveyBatch.id == batch_id,\n            *filters,\n        )\n    )\n\n\ndef _safe_file_name(name: str) -> str:\n    base = Path(name or "upload.xlsx").name\n    base = re.sub(r"[^0-9A-Za-zÀ-ỹ._() -]+", "_", base)\n    base = re.sub(r"\\s+", "_", base).strip("._")\n    return base[:220] or "upload.xlsx"\n\n\ndef _new_job_code() -> str:\n    now = datetime.now()\n    return (\n        "IMP-"\n        + now.strftime("%Y%m%d-%H%M%S")\n        + "-"\n        + uuid4().hex[:6].upper()\n    )\n\n\ndef _add_issue(\n    db: Session,\n    job: HouseholdImportJob,\n    *,\n    severity: str,\n    code: str,\n    message: str,\n    sheet_name: str | None = None,\n    row_number: int | None = None,\n    column_name: str | None = None,\n) -> None:\n    db.add(\n        HouseholdImportError(\n            job_id=job.id,\n            severity=severity,\n            sheet_name=sheet_name,\n            row_number=row_number,\n            column_name=column_name,\n            error_code=code,\n            message=message,\n        )\n    )\n\n\ndef _xlsx_structure(content: bytes) -> tuple[list[str], bool]:\n    if not content.startswith(b"PK\\x03\\x04"):\n        raise ValueError("Tệp .xlsx không có cấu trúc ZIP hợp lệ.")\n\n    with zipfile.ZipFile(BytesIO(content)) as archive:\n        names = set(archive.namelist())\n        if "xl/workbook.xml" not in names:\n            raise ValueError("Không tìm thấy xl/workbook.xml.")\n\n        has_macro = any(\n            item.lower().endswith("vbaproject.bin")\n            for item in names\n        )\n\n        xml = archive.read("xl/workbook.xml")\n        root = ElementTree.fromstring(xml)\n        sheet_names: list[str] = []\n        for item in root.iter():\n            if item.tag.endswith("}sheet") or item.tag == "sheet":\n                name = str(item.attrib.get("name") or "").strip()\n                if name:\n                    sheet_names.append(name)\n\n        return sheet_names, has_macro\n\n\ndef _xls_macro_hint(content: bytes) -> bool:\n    marker_ascii = b"_VBA_PROJECT_CUR"\n    marker_utf16 = "_VBA_PROJECT_CUR".encode("utf-16le")\n    return marker_ascii in content or marker_utf16 in content\n\n\ndef _store_received_file(\n    job_code: str,\n    file_name: str,\n    content: bytes,\n) -> Path:\n    folder = IMPORT_ROOT / job_code\n    folder.mkdir(parents=True, exist_ok=True)\n    path = folder / _safe_file_name(file_name)\n    path.write_bytes(content)\n    return path\n\n\ndef _json_result(\n    *,\n    ok: bool,\n    job: HouseholdImportJob | None,\n    message: str,\n    status_code: int = 200,\n) -> JSONResponse:\n    return JSONResponse(\n        status_code=status_code,\n        content={\n            "ok": ok,\n            "job_code": job.job_code if job is not None else None,\n            "status": job.status if job is not None else None,\n            "status_label": (\n                IMPORT_STATUS_LABELS.get(job.status, job.status)\n                if job is not None\n                else None\n            ),\n            "message": message,\n            "redirect_url": (\n                f"/dieu-tra/cap-nhat-ho-dan/lan-gui/{job.job_code}"\n                if job is not None\n                else None\n            ),\n        },\n    )\n\n\n@router.get("/cap-nhat-ho-dan", response_class=HTMLResponse)\ndef household_update_center(\n    request: Request,\n    school_year_id: int | None = None,\n    batch_id: int | None = None,\n    db: Session = Depends(get_db),\n):\n    role_code = _role(request)\n    if role_code not in VIEW_ROLE_CODES:\n        return RedirectResponse(url="/?status=forbidden", status_code=303)\n\n    school_years = list(\n        db.scalars(\n            select(SchoolYear)\n            .where(SchoolYear.is_active.is_(True))\n            .order_by(SchoolYear.code.desc())\n        ).all()\n    )\n\n    filters = tao_bo_loc_dot_theo_nguoi_dung(request)\n    statement = (\n        select(SurveyBatch)\n        .options(\n            selectinload(SurveyBatch.school_year),\n            selectinload(SurveyBatch.commune),\n        )\n        .where(*filters)\n        .order_by(\n            SurveyBatch.school_year_id.desc(),\n            SurveyBatch.created_at.desc(),\n            SurveyBatch.id.desc(),\n        )\n    )\n    if school_year_id is not None:\n        statement = statement.where(\n            SurveyBatch.school_year_id == school_year_id\n        )\n    batches = list(db.scalars(statement).all())\n\n    batch_ids = [item.id for item in batches]\n    selected_batch_id = (\n        batch_id\n        if batch_id in batch_ids\n        else (batch_ids[0] if batch_ids else None)\n    )\n\n    jobs: list[HouseholdImportJob] = []\n    if batch_ids:\n        jobs = list(\n            db.scalars(\n                select(HouseholdImportJob)\n                .where(\n                    HouseholdImportJob.survey_batch_id.in_(batch_ids)\n                )\n                .order_by(\n                    HouseholdImportJob.created_at.desc(),\n                    HouseholdImportJob.id.desc(),\n                )\n                .limit(100)\n            ).all()\n        )\n\n    can_upload = role_code in UPLOAD_ROLE_CODES\n\n    return templates.TemplateResponse(\n        request=request,\n        name="surveys/household_update_center_v1.html",\n        context={\n            "nguoi_dung": request.scope.get("auth_user"),\n            "school_years": school_years,\n            "selected_school_year_id": school_year_id,\n            "selected_batch_id": selected_batch_id,\n            "batches": batches,\n            "jobs": jobs,\n            "can_upload": can_upload,\n            "scope_label": _scope_label(request),\n            "batch_status_labels": BATCH_STATUS_LABELS,\n            "import_status_labels": IMPORT_STATUS_LABELS,\n            "import_status_classes": IMPORT_STATUS_CLASSES,\n        },\n    )\n\n\n@router.post("/{batch_id}/cap-nhat-ho-dan/gui-file")\nasync def receive_household_update_file(\n    batch_id: int,\n    request: Request,\n    excel_file: UploadFile = File(...),\n    db: Session = Depends(get_db),\n):\n    role_code = _role(request)\n    if role_code not in UPLOAD_ROLE_CODES:\n        return _json_result(\n            ok=False,\n            job=None,\n            message="Tài khoản không có quyền gửi file cập nhật hộ dân.",\n            status_code=403,\n        )\n\n    batch = _batch_in_scope(db, request, batch_id)\n    if batch is None:\n        return _json_result(\n            ok=False,\n            job=None,\n            message="Đợt điều tra không thuộc phạm vi của tài khoản.",\n            status_code=403,\n        )\n\n    try:\n        db.execute(text("PRAGMA busy_timeout=15000"))\n    except Exception:\n        pass\n\n    original_name = excel_file.filename or "khong_ten"\n    ext = Path(original_name).suffix.lower()\n    content = await excel_file.read()\n\n    user = _user(request)\n    job = HouseholdImportJob(\n        job_code=_new_job_code(),\n        survey_batch_id=batch.id,\n        school_year_id=batch.school_year_id,\n        commune_id=batch.commune_id,\n        uploaded_by_user_id=user.get("id"),\n        actor_name_snapshot=user.get("full_name"),\n        actor_role_snapshot=user.get("role_name") or user.get("role_code"),\n        actor_unit_snapshot=user.get("unit_name"),\n        original_file_name=original_name,\n        file_ext=ext,\n        file_size=len(content),\n        status="DA_NHAN",\n        stage="TIEP_NHAN",\n        message="Máy chủ đã nhận file và cấp mã lần gửi.",\n        received_at=datetime.now(),\n    )\n    db.add(job)\n    db.commit()\n    db.refresh(job)\n\n    if not content:\n        job.status = "LOI_FILE"\n        job.stage = "KIEM_TRA"\n        job.message = "File tải lên đang trống."\n        job.checked_at = datetime.now()\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="EMPTY_FILE",\n            message="File tải lên không có dữ liệu.",\n        )\n        db.commit()\n        return _json_result(\n            ok=False,\n            job=job,\n            message=job.message,\n        )\n\n    if len(content) > 25 * 1024 * 1024:\n        job.status = "LOI_FILE"\n        job.stage = "KIEM_TRA"\n        job.message = "File lớn quá 25 MB."\n        job.checked_at = datetime.now()\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="FILE_TOO_LARGE",\n            message="Kích thước file vượt giới hạn 25 MB.",\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n    digest = hashlib.sha256(content).hexdigest()\n    job.sha256 = digest\n\n    duplicate = db.scalar(\n        select(HouseholdImportJob)\n        .where(\n            HouseholdImportJob.survey_batch_id == batch.id,\n            HouseholdImportJob.sha256 == digest,\n            HouseholdImportJob.id != job.id,\n        )\n        .order_by(HouseholdImportJob.created_at.desc())\n    )\n    if duplicate is not None:\n        job.status = "TRUNG_FILE"\n        job.stage = "KIEM_TRA"\n        job.duplicate_of_job_code = duplicate.job_code\n        job.message = (\n            "Nội dung file này đã được gửi trước đó ở lần "\n            f"{duplicate.job_code}. Hệ thống không tạo bản cập nhật trùng."\n        )\n        job.checked_at = datetime.now()\n        _add_issue(\n            db,\n            job,\n            severity="WARNING",\n            code="DUPLICATE_FILE",\n            message=job.message,\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n    if ext not in {".xls", ".xlsx"}:\n        job.status = "LOI_DINH_DANG"\n        job.stage = "KIEM_TRA"\n        job.message = "Chỉ chấp nhận file Excel .xls hoặc .xlsx."\n        job.checked_at = datetime.now()\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="INVALID_EXTENSION",\n            message=job.message,\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n    try:\n        stored = _store_received_file(\n            job.job_code,\n            original_name,\n            content,\n        )\n        job.stored_path = str(stored.relative_to(PROJECT_DIR))\n    except Exception as error:\n        job.status = "LOI_FILE"\n        job.stage = "LUU_FILE"\n        job.message = (\n            "Máy chủ đã nhận file nhưng không lưu được bản an toàn. "\n            f"Lỗi: {type(error).__name__}."\n        )\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="STORE_FAILED",\n            message=job.message,\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n    if bool(getattr(batch, "is_locked", False)) or batch.status == "DA_KET_THUC":\n        job.status = "LOI_DOT_KHOA"\n        job.stage = "KIEM_TRA"\n        job.message = (\n            "File đã được nhận và lưu an toàn, nhưng đợt điều tra "\n            "đang khóa/đã kết thúc nên chưa được phép cập nhật dữ liệu."\n        )\n        job.checked_at = datetime.now()\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="BATCH_LOCKED",\n            message=job.message,\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n    job.status = "DANG_KIEM_TRA"\n    job.stage = "KIEM_TRA"\n    db.commit()\n\n    try:\n        if ext == ".xlsx":\n            sheet_names, has_macro = _xlsx_structure(content)\n            job.sheet_names = json.dumps(\n                sheet_names,\n                ensure_ascii=False,\n            )\n            job.has_macro = 1 if has_macro else 0\n            job.checked_at = datetime.now()\n            job.status = "DA_KIEM_TRA_CAU_TRUC"\n            job.stage = "CHO_ANH_XA_DU_LIEU"\n            job.message = (\n                "Đã nhận và kiểm tra cấu trúc file .xlsx. "\n                "File chưa ghi vào dữ liệu hộ dân ở bước V1A; "\n                "đang chờ bộ ánh xạ theo mẫu chính thức."\n            )\n            if has_macro:\n                _add_issue(\n                    db,\n                    job,\n                    severity="WARNING",\n                    code="MACRO_PRESENT",\n                    message=(\n                        "Phát hiện thành phần VBA/macro trong file .xlsx. "\n                        "Phần mềm không thực thi macro."\n                    ),\n                )\n\n        else:\n            ole_magic = bytes.fromhex("D0CF11E0A1B11AE1")\n            if not content.startswith(ole_magic):\n                raise ValueError(\n                    "Tệp .xls không có chữ ký OLE/Compound Document hợp lệ."\n                )\n\n            has_macro = _xls_macro_hint(content)\n            job.has_macro = 1 if has_macro else 0\n            job.checked_at = datetime.now()\n            job.status = "CHO_XU_LY_XLS"\n            job.stage = "CHO_BO_DOC_XLS"\n            job.message = (\n                "Đã nhận an toàn file Excel 97-2003 (.xls). "\n                "Macro/mã nhúng không được chạy. "\n                "Bản V1A lưu file và lịch sử; bước V1B sẽ đọc dữ liệu "\n                "theo đúng cấu trúc mẫu để cập nhật CSDL."\n            )\n            if has_macro:\n                _add_issue(\n                    db,\n                    job,\n                    severity="INFO",\n                    code="XLS_HAS_VBA",\n                    message=(\n                        "File .xls có dấu hiệu chứa VBA/macro. "\n                        "Phần mềm chỉ lưu tệp dưới dạng dữ liệu nhị phân, "\n                        "không thực thi mã nhúng."\n                    ),\n                )\n\n        db.commit()\n        return _json_result(ok=True, job=job, message=job.message)\n\n    except Exception as error:\n        job.status = "LOI_DINH_DANG"\n        job.stage = "KIEM_TRA"\n        job.checked_at = datetime.now()\n        job.message = (\n            "Máy chủ đã nhận file nhưng kiểm tra cấu trúc không đạt: "\n            f"{type(error).__name__}: {error}"\n        )\n        _add_issue(\n            db,\n            job,\n            severity="ERROR",\n            code="STRUCTURE_ERROR",\n            message=job.message,\n        )\n        db.commit()\n        return _json_result(ok=False, job=job, message=job.message)\n\n\ndef _job_in_scope(\n    db: Session,\n    request: Request,\n    job_code: str,\n) -> HouseholdImportJob | None:\n    filters = tao_bo_loc_dot_theo_nguoi_dung(request)\n    batch_ids = list(\n        db.scalars(\n            select(SurveyBatch.id).where(*filters)\n        ).all()\n    )\n    if not batch_ids:\n        return None\n    return db.scalar(\n        select(HouseholdImportJob).where(\n            HouseholdImportJob.job_code == job_code,\n            HouseholdImportJob.survey_batch_id.in_(batch_ids),\n        )\n    )\n\n\n@router.get(\n    "/cap-nhat-ho-dan/lan-gui/{job_code}",\n    response_class=HTMLResponse,\n)\ndef household_import_detail(\n    job_code: str,\n    request: Request,\n    db: Session = Depends(get_db),\n):\n    if _role(request) not in VIEW_ROLE_CODES:\n        return RedirectResponse(url="/?status=forbidden", status_code=303)\n\n    job = _job_in_scope(db, request, job_code)\n    if job is None:\n        return RedirectResponse(\n            url="/dieu-tra/cap-nhat-ho-dan",\n            status_code=303,\n        )\n\n    batch = db.scalar(\n        select(SurveyBatch)\n        .options(\n            selectinload(SurveyBatch.school_year),\n            selectinload(SurveyBatch.commune),\n        )\n        .where(SurveyBatch.id == job.survey_batch_id)\n    )\n    errors = list(\n        db.scalars(\n            select(HouseholdImportError)\n            .where(HouseholdImportError.job_id == job.id)\n            .order_by(\n                HouseholdImportError.id.asc()\n            )\n        ).all()\n    )\n\n    sheet_names = []\n    if job.sheet_names:\n        try:\n            sheet_names = json.loads(job.sheet_names)\n        except Exception:\n            sheet_names = [job.sheet_names]\n\n    return templates.TemplateResponse(\n        request=request,\n        name="surveys/household_import_detail_v1.html",\n        context={\n            "nguoi_dung": request.scope.get("auth_user"),\n            "job": job,\n            "batch": batch,\n            "errors": errors,\n            "sheet_names": sheet_names,\n            "status_label": IMPORT_STATUS_LABELS.get(\n                job.status,\n                job.status,\n            ),\n            "status_class": IMPORT_STATUS_CLASSES.get(\n                job.status,\n                "info",\n            ),\n        },\n    )\n\n\n@router.get("/cap-nhat-ho-dan/mau-cap-nhat-goc")\ndef download_original_update_sample(\n    request: Request,\n):\n    if _role(request) not in VIEW_ROLE_CODES:\n        return RedirectResponse(url="/?status=forbidden", status_code=303)\n\n    path = REFERENCE_DIR / "pcgd_nhapphieudieutra_2025.xls"\n    if not path.exists():\n        return RedirectResponse(\n            url="/dieu-tra/cap-nhat-ho-dan",\n            status_code=303,\n        )\n    return FileResponse(\n        path=str(path),\n        filename="pcgd_nhapphieudieutra_2025.xls",\n        media_type="application/vnd.ms-excel",\n    )\n\n\n@router.get("/cap-nhat-ho-dan/mau-phieu-dieu-tra")\ndef download_official_survey_form_sample(\n    request: Request,\n):\n    if _role(request) not in VIEW_ROLE_CODES:\n        return RedirectResponse(url="/?status=forbidden", status_code=303)\n\n    path = (\n        REFERENCE_DIR\n        / "mau-phieu-dieu-tra-pho-cap-giao-duc-xoa-mu-chu.xlsx"\n    )\n    if not path.exists():\n        return RedirectResponse(\n            url="/dieu-tra/cap-nhat-ho-dan",\n            status_code=303,\n        )\n    return FileResponse(\n        path=str(path),\n        filename="mau-phieu-dieu-tra-pho-cap-giao-duc-xoa-mu-chu.xlsx",\n        media_type=(\n            "application/vnd.openxmlformats-officedocument."\n            "spreadsheetml.sheet"\n        ),\n    )\n\n\ndef _age_on(value, reference_date: date) -> int | None:\n    if value is None:\n        return None\n    return (\n        reference_date.year\n        - value.year\n        - (\n            (reference_date.month, reference_date.day)\n            < (value.month, value.day)\n        )\n    )\n\n\ndef _normalize_no_accent(value: str) -> str:\n    import unicodedata\n\n    text_value = unicodedata.normalize(\n        "NFD",\n        str(value or "").lower(),\n    )\n    text_value = "".join(\n        char\n        for char in text_value\n        if unicodedata.category(char) != "Mn"\n    )\n    return re.sub(r"\\s+", " ", text_value).strip()\n\n\ndef _level_from_record(\n    record: SurveyPersonYearRecord | None,\n    school: School | None,\n    classroom: Classroom | None,\n) -> str:\n    if record is None:\n        return "CHUA_XAC_DINH"\n\n    school_name = (\n        record.school_name_reported\n        or (school.name if school is not None else "")\n        or ""\n    )\n    class_name = (\n        record.class_name_reported\n        or (classroom.name if classroom is not None else "")\n        or ""\n    )\n    key = _normalize_no_accent(f"{school_name} {class_name}")\n\n    if any(x in key for x in ("mam non", "mau giao", "nha tre")):\n        return "MN"\n    if any(x in key for x in ("trung hoc pho thong", "thpt")):\n        return "THPT"\n    if any(x in key for x in ("trung hoc co so", "thcs")):\n        return "THCS"\n    if "tieu hoc" in key:\n        return "TH"\n\n    match = re.search(r"(?:lop\\s*)?(\\d{1,2})(?:\\D|$)", key)\n    if match:\n        grade = int(match.group(1))\n        if 1 <= grade <= 5:\n            return "TH"\n        if 6 <= grade <= 9:\n            return "THCS"\n        if 10 <= grade <= 12:\n            return "THPT"\n\n    if record.learning_status in {\n        "CHUA_DI_HOC",\n        "BO_HOC",\n        "THOI_HOC",\n    }:\n        return "NGOAI_NHA_TRUONG"\n\n    return "CHUA_XAC_DINH"\n\n\n@router.get(\n    "/{batch_id}/cap-nhat-ho-dan/thong-ke",\n    response_class=HTMLResponse,\n)\ndef household_related_statistics(\n    batch_id: int,\n    request: Request,\n    db: Session = Depends(get_db),\n):\n    batch = _batch_in_scope(db, request, batch_id)\n    if batch is None:\n        return RedirectResponse(\n            url="/dieu-tra/cap-nhat-ho-dan",\n            status_code=303,\n        )\n\n    scope_filters = tao_bo_loc_bao_cao_theo_nguoi_dung(request)\n    forms = list(\n        db.scalars(\n            select(SurveyForm)\n            .join(\n                Household,\n                Household.id == SurveyForm.household_id,\n            )\n            .options(\n                selectinload(SurveyForm.household)\n                .selectinload(Household.people),\n            )\n            .where(\n                SurveyForm.survey_batch_id == batch.id,\n                *scope_filters,\n            )\n        ).all()\n    )\n\n    people = [\n        person\n        for form in forms\n        for person in form.household.people\n        if person.is_active\n    ]\n    form_ids = [item.id for item in forms]\n    person_ids = [item.id for item in people]\n\n    records = []\n    if form_ids and person_ids:\n        records = list(\n            db.scalars(\n                select(SurveyPersonYearRecord).where(\n                    SurveyPersonYearRecord.survey_form_id.in_(form_ids),\n                    SurveyPersonYearRecord.survey_person_id.in_(person_ids),\n                    SurveyPersonYearRecord.school_year_id\n                    == batch.school_year_id,\n                )\n            ).all()\n        )\n\n    record_by_person = {\n        item.survey_person_id: item\n        for item in records\n    }\n\n    school_ids = {\n        item.school_id\n        for item in records\n        if item.school_id is not None\n    }\n    class_ids = {\n        item.class_id\n        for item in records\n        if item.class_id is not None\n    }\n    schools = {\n        item.id: item\n        for item in db.scalars(\n            select(School).where(School.id.in_(school_ids))\n        ).all()\n    } if school_ids else {}\n    classrooms = {\n        item.id: item\n        for item in db.scalars(\n            select(Classroom).where(Classroom.id.in_(class_ids))\n        ).all()\n    } if class_ids else {}\n\n    reference_date = batch.start_date or date.today()\n    total_pcgd = 0\n    total_xmc = 0\n    total_age_18 = 0\n    missing_personal_id = 0\n    missing_citizen_id = 0\n    missing_year_record = 0\n\n    levels = {\n        "MN": 0,\n        "TH": 0,\n        "THCS": 0,\n        "THPT": 0,\n        "NGOAI_NHA_TRUONG": 0,\n        "CHUA_XAC_DINH": 0,\n    }\n    learning = {\n        code: 0\n        for code in LEARNING_STATUS_LABELS\n    }\n    residency = {\n        code: 0\n        for code in RESIDENCY_STATUS_LABELS\n    }\n    form_status = {\n        code: 0\n        for code in FORM_STATUS_LABELS\n    }\n\n    for form in forms:\n        form_status[form.status] = form_status.get(form.status, 0) + 1\n\n    for person in people:\n        age = _age_on(person.date_of_birth, reference_date)\n        if age is not None and 0 <= age <= 18:\n            total_pcgd += 1\n        if age is not None and 18 <= age <= 60:\n            total_xmc += 1\n        if age == 18:\n            total_age_18 += 1\n\n        if not (person.personal_id or "").strip():\n            missing_personal_id += 1\n        if not (getattr(person, "citizen_id", None) or "").strip():\n            missing_citizen_id += 1\n\n        residency[person.residency_status] = (\n            residency.get(person.residency_status, 0) + 1\n        )\n\n        record = record_by_person.get(person.id)\n        if record is None:\n            missing_year_record += 1\n            levels["CHUA_XAC_DINH"] += 1\n            continue\n\n        learning[record.learning_status] = (\n            learning.get(record.learning_status, 0) + 1\n        )\n        level = _level_from_record(\n            record,\n            schools.get(record.school_id),\n            classrooms.get(record.class_id),\n        )\n        levels[level] = levels.get(level, 0) + 1\n\n    return templates.TemplateResponse(\n        request=request,\n        name="surveys/household_statistics_v1.html",\n        context={\n            "nguoi_dung": request.scope.get("auth_user"),\n            "batch": batch,\n            "reference_date": reference_date,\n            "scope_label": _scope_label(request),\n            "total_households": len(forms),\n            "total_people": len(people),\n            "total_pcgd": total_pcgd,\n            "total_xmc": total_xmc,\n            "total_age_18": total_age_18,\n            "missing_personal_id": missing_personal_id,\n            "missing_citizen_id": missing_citizen_id,\n            "missing_year_record": missing_year_record,\n            "level_counts": levels,\n            "level_labels": {\n                "MN": "Mầm non",\n                "TH": "Tiểu học",\n                "THCS": "THCS",\n                "THPT": "THPT",\n                "NGOAI_NHA_TRUONG": "Ngoài nhà trường",\n                "CHUA_XAC_DINH": "Chưa xác định",\n            },\n            "learning_counts": learning,\n            "learning_labels": LEARNING_STATUS_LABELS,\n            "residency_counts": residency,\n            "residency_labels": RESIDENCY_STATUS_LABELS,\n            "form_status_counts": form_status,\n            "form_status_labels": FORM_STATUS_LABELS,\n        },\n    )\n',
    "app/templates/surveys/household_update_center_v1.html": '<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Cập nhật dữ liệu hộ dân</title>\n    <link rel="stylesheet" href="/static/css/style.css">\n    <style>\n        :root{--blue:#0f5fa8;--blue2:#1976d2;--bg:#eef4f9;--line:#d8e4ef;--text:#17324d}\n        *{box-sizing:border-box}\n        body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,sans-serif}\n        .hero{background:linear-gradient(135deg,#0f5fa8,#1682d6);color:#fff;padding:26px 3vw}\n        .hero-inner,.wrap{max-width:1500px;margin:auto}\n        .hero h1{margin:6px 0 8px;font-size:30px}\n        .hero p{margin:0;opacity:.94}\n        .wrap{padding:22px 3vw 48px}\n        .panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:18px;box-shadow:0 7px 20px rgba(23,50,77,.05)}\n        .notice{border-radius:13px;padding:15px 17px;line-height:1.55;margin-bottom:14px}\n        .notice.info{background:#eaf5ff;border:1px solid #a9d2f5}\n        .notice.warn{background:#fff7df;border:1px solid #efcf7d}\n        .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}\n        .field label{display:block;font-weight:800;margin-bottom:7px}\n        .control{width:100%;min-height:45px;border:1px solid #bfd0df;border-radius:10px;padding:9px 11px;background:#fff;font:inherit}\n        .actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n        .btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border:0;border-radius:10px;padding:10px 15px;text-decoration:none;font-weight:800;cursor:pointer}\n        .primary{background:var(--blue2);color:#fff}.secondary{background:#e9f0f6;color:var(--text)}.warning{background:#fff0ca;color:#855200}\n        .upload-row{display:grid;grid-template-columns:1fr 1.5fr auto;gap:12px;align-items:end}\n        .upload-status{margin-top:14px;display:grid;gap:8px}\n        .upload-item{padding:12px;border:1px solid var(--line);border-radius:12px;background:#f8fbfd}\n        .upload-item strong{display:block;margin-bottom:5px}\n        .upload-item .ok{color:#19723b}.upload-item .bad{color:#b42318}.upload-item .wait{color:#9a6200}\n        .table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:13px}\n        table{width:100%;border-collapse:collapse;min-width:1050px}\n        th,td{padding:10px 11px;border-bottom:1px solid #e6edf3;text-align:left;vertical-align:top}\n        th{background:#eaf2f9;font-size:13px}\n        .pill{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:800}\n        .pill.info{background:#dceeff;color:#0b5cab}.pill.success{background:#dcf6e5;color:#146b35}.pill.warning{background:#fff0c9;color:#835500}.pill.danger{background:#ffe2df;color:#a52a22}\n        .small{font-size:12px;color:#61768a}\n        .ref-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n        .ref-card{border:1px solid var(--line);border-radius:13px;padding:15px;background:#fafcfe}\n        @media(max-width:900px){.grid,.upload-row,.ref-grid{grid-template-columns:1fr}.hero h1{font-size:24px}.wrap{padding-left:12px;padding-right:12px}}\n    </style>\n</head>\n<body>\n{% include "partials/dropdown_menu_v1.html" %}\n\n<header class="hero">\n    <div class="hero-inner">\n        <div style="font-size:13px;font-weight:800;letter-spacing:.08em">BÀI 13B-9 V1A · CẬP NHẬT DỮ LIỆU HỘ DÂN</div>\n        <h1>Tiếp nhận nhiều file Excel an toàn</h1>\n        <p>{{ scope_label }} · Nhận độc lập từng file, chống gửi trùng, lưu lịch sử và không chạy macro.</p>\n    </div>\n</header>\n\n<main class="wrap">\n    <section class="panel">\n        <div class="notice info">\n            <strong>Nguyên tắc xử lý nhiều file:</strong> mỗi file được cấp một mã lần gửi riêng\n            <code>IMP-...</code>. Nhiều người có thể gửi trong cùng khoảng thời gian; mỗi file được\n            tiếp nhận, kiểm tra và lưu lịch sử độc lập. File lỗi không làm ảnh hưởng file đúng.\n        </div>\n        <div class="notice warn">\n            <strong>Giai đoạn V1A chưa ghi dữ liệu hộ dân vào CSDL.</strong>\n            Bản này tạo nền an toàn: nhận file, xác nhận “Đã nhận”, phát hiện file trùng,\n            kiểm tra định dạng, lưu lịch sử và chuẩn bị bộ ánh xạ mẫu chính thức.\n            File <strong>.xls</strong> mẫu có thành phần VBA/macro; phần mềm tuyệt đối không thực thi macro.\n            Bài V1B sẽ đọc dữ liệu của mẫu và thực hiện cập nhật theo giao dịch/rollback.\n        </div>\n        <div class="ref-grid">\n            <div class="ref-card">\n                <strong>Mẫu cập nhật dữ liệu gốc</strong>\n                <p class="small">Excel 97–2003 (.xls) do đơn vị cung cấp. Khi mở bằng Excel nên để macro ở trạng thái tắt nếu không cần.</p>\n                <a class="btn secondary" href="/dieu-tra/cap-nhat-ho-dan/mau-cap-nhat-goc">⬇ Tải mẫu cập nhật .xls</a>\n            </div>\n            <div class="ref-card">\n                <strong>Mẫu phiếu điều tra chính thức</strong>\n                <p class="small">Mẫu dùng làm chuẩn cho bản in phiếu thực địa A4 nằm ngang.</p>\n                <a class="btn secondary" href="/dieu-tra/cap-nhat-ho-dan/mau-phieu-dieu-tra">⬇ Tải mẫu phiếu điều tra</a>\n            </div>\n        </div>\n    </section>\n\n    <section class="panel">\n        <h2 style="margin-top:0">Chọn phạm vi</h2>\n        <form method="get" action="/dieu-tra/cap-nhat-ho-dan">\n            <div class="grid">\n                <div class="field">\n                    <label for="school_year_id">Năm học</label>\n                    <select class="control" id="school_year_id" name="school_year_id">\n                        <option value="">Tất cả năm học</option>\n                        {% for year in school_years %}\n                        <option value="{{ year.id }}" {% if selected_school_year_id == year.id %}selected{% endif %}>{{ year.code }}</option>\n                        {% endfor %}\n                    </select>\n                </div>\n                <div class="field">\n                    <label for="batch_id_filter">Đợt điều tra</label>\n                    <select class="control" id="batch_id_filter" name="batch_id">\n                        {% for batch in batches %}\n                        <option value="{{ batch.id }}" {% if selected_batch_id == batch.id %}selected{% endif %}>\n                            {{ batch.school_year.code }} · {{ batch.commune.name }} · {{ batch.name }}\n                        </option>\n                        {% else %}\n                        <option value="">Không có đợt phù hợp</option>\n                        {% endfor %}\n                    </select>\n                </div>\n                <div class="field" style="display:flex;align-items:end">\n                    <button class="btn primary" type="submit">Lọc / chọn đợt</button>\n                </div>\n            </div>\n        </form>\n    </section>\n\n    {% if can_upload %}\n    <section class="panel">\n        <h2 style="margin-top:0">Gửi file cập nhật</h2>\n        <div class="upload-row">\n            <div class="field">\n                <label for="upload_batch">Đợt nhận dữ liệu</label>\n                <select class="control" id="upload_batch">\n                    {% for batch in batches %}\n                    <option value="{{ batch.id }}" {% if selected_batch_id == batch.id %}selected{% endif %}>\n                        {{ batch.school_year.code }} · {{ batch.commune.name }} · {{ batch.name }}\n                        {% if batch.is_locked %} · ĐÃ KHÓA{% endif %}\n                    </option>\n                    {% endfor %}\n                </select>\n            </div>\n            <div class="field">\n                <label for="excel_files">Chọn một hoặc nhiều file .xls / .xlsx</label>\n                <input class="control" id="excel_files" type="file" accept=".xls,.xlsx" multiple>\n                <div class="small" style="margin-top:6px">Tối đa 25 MB mỗi file. Có thể chọn nhiều file; hệ thống gửi từng file độc lập.</div>\n            </div>\n            <button class="btn primary" id="send_files" type="button">⬆ Gửi file</button>\n        </div>\n        <div id="upload_status" class="upload-status"></div>\n    </section>\n    {% else %}\n    <section class="panel">\n        <div class="notice info">Tài khoản hiện tại chỉ được xem lịch sử và thống kê, không được gửi file cập nhật.</div>\n    </section>\n    {% endif %}\n\n    <section class="panel">\n        <div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap">\n            <div>\n                <h2 style="margin:0">Thống kê hộ dân và các yếu tố liên quan</h2>\n                <p class="small">Thống kê theo toàn bộ thành viên của hộ, không giới hạn theo cấp học của giáo viên.</p>\n            </div>\n            {% if selected_batch_id %}\n            <a class="btn secondary" href="/dieu-tra/{{ selected_batch_id }}/cap-nhat-ho-dan/thong-ke">📊 Mở thống kê</a>\n            {% endif %}\n        </div>\n    </section>\n\n    <section class="panel">\n        <h2 style="margin-top:0">Lịch sử gửi Excel</h2>\n        <div class="table-wrap">\n            <table>\n                <thead>\n                    <tr>\n                        <th>Thời gian</th>\n                        <th>Mã lần gửi</th>\n                        <th>File</th>\n                        <th>Người/đơn vị gửi</th>\n                        <th>Trạng thái</th>\n                        <th>Kích thước / SHA256</th>\n                        <th>Chi tiết</th>\n                    </tr>\n                </thead>\n                <tbody>\n                {% for job in jobs %}\n                    <tr>\n                        <td>{{ job.created_at.strftime(\'%d/%m/%Y %H:%M:%S\') }}</td>\n                        <td><strong>{{ job.job_code }}</strong></td>\n                        <td>{{ job.original_file_name }}<div class="small">{{ job.file_ext }}</div></td>\n                        <td>{{ job.actor_name_snapshot or \'\' }}<div class="small">{{ job.actor_unit_snapshot or \'\' }}</div></td>\n                        <td>\n                            <span class="pill {{ import_status_classes.get(job.status, \'info\') }}">\n                                {{ import_status_labels.get(job.status, job.status) }}\n                            </span>\n                            {% if job.duplicate_of_job_code %}\n                            <div class="small">Trùng: {{ job.duplicate_of_job_code }}</div>\n                            {% endif %}\n                        </td>\n                        <td>{{ \'%.1f\'|format(job.file_size / 1024) }} KB<div class="small">{{ (job.sha256 or \'\')[:16] }}{% if job.sha256 %}…{% endif %}</div></td>\n                        <td><a class="btn secondary" href="/dieu-tra/cap-nhat-ho-dan/lan-gui/{{ job.job_code }}">Xem kết quả</a></td>\n                    </tr>\n                {% else %}\n                    <tr><td colspan="7">Chưa có lần gửi file nào trong phạm vi đang xem.</td></tr>\n                {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </section>\n</main>\n\n{% if can_upload %}\n<script>\n(function(){\n    const button = document.getElementById(\'send_files\');\n    const input = document.getElementById(\'excel_files\');\n    const batch = document.getElementById(\'upload_batch\');\n    const box = document.getElementById(\'upload_status\');\n\n    function addRow(file) {\n        const row = document.createElement(\'div\');\n        row.className = \'upload-item\';\n        row.innerHTML = \'<strong></strong><div class="wait">Đang chuẩn bị gửi…</div>\';\n        row.querySelector(\'strong\').textContent = file.name;\n        box.prepend(row);\n        return row;\n    }\n\n    async function sendOne(file) {\n        const row = addRow(file);\n        const status = row.querySelector(\'div\');\n        const batchId = batch.value;\n        if (!batchId) {\n            status.className = \'bad\';\n            status.textContent = \'Chưa chọn đợt điều tra.\';\n            return;\n        }\n\n        status.className = \'wait\';\n        status.textContent = \'Đang gửi… Chưa có xác nhận của máy chủ.\';\n\n        const formData = new FormData();\n        formData.append(\'excel_file\', file, file.name);\n\n        try {\n            const response = await fetch(\'/dieu-tra/\' + batchId + \'/cap-nhat-ho-dan/gui-file\', {\n                method: \'POST\',\n                body: formData,\n                headers: {\'X-Requested-With\': \'fetch\'}\n            });\n            const contentType = response.headers.get(\'content-type\') || \'\';\n            if (!contentType.includes(\'application/json\')) {\n                throw new Error(\'Máy chủ không trả xác nhận JSON.\');\n            }\n            const result = await response.json();\n\n            if (result.job_code) {\n                status.className = result.ok ? \'ok\' : \'bad\';\n                status.innerHTML =\n                    \'<strong>\' + (result.status_label || \'Đã nhận\') + \'</strong><br>\' +\n                    \'Mã lần gửi: <b>\' + result.job_code + \'</b><br>\' +\n                    (result.message || \'\') +\n                    (result.redirect_url\n                        ? \'<br><a href="\' + result.redirect_url + \'">Xem chi tiết lần gửi</a>\'\n                        : \'\');\n            } else {\n                status.className = \'bad\';\n                status.textContent = result.message || \'Máy chủ từ chối file.\';\n            }\n        } catch (error) {\n            status.className = \'bad\';\n            status.innerHTML =\n                \'<strong>Không gửi được / mất kết nối</strong><br>\' +\n                \'Máy chủ chưa xác nhận đã nhận file này. Hãy kiểm tra mục Lịch sử gửi trước khi bấm gửi lại.<br>\' +\n                \'<span class="small">\' + String(error) + \'</span>\';\n        }\n    }\n\n    button.addEventListener(\'click\', async function(){\n        const files = Array.from(input.files || []);\n        if (!files.length) {\n            alert(\'Hãy chọn ít nhất một file Excel.\');\n            return;\n        }\n        button.disabled = true;\n        await Promise.allSettled(files.map(sendOne));\n        button.disabled = false;\n    });\n})();\n</script>\n{% endif %}\n</body>\n</html>\n',
    "app/templates/surveys/household_import_detail_v1.html": '<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{{ job.job_code }} · Kết quả nhận file</title>\n    <link rel="stylesheet" href="/static/css/style.css">\n    <style>\n        *{box-sizing:border-box}body{margin:0;background:#eef4f9;color:#17324d;font-family:Arial,sans-serif}\n        .hero{background:#0f5fa8;color:#fff;padding:25px 3vw}.wrap,.hero-inner{max-width:1250px;margin:auto}.wrap{padding:22px 3vw 48px}\n        .panel{background:#fff;border:1px solid #d8e4ef;border-radius:16px;padding:20px;margin-bottom:16px}\n        .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px 24px}.item{padding:9px 0;border-bottom:1px solid #edf1f5}\n        .pill{display:inline-block;padding:7px 11px;border-radius:999px;font-weight:800}.pill.info{background:#dceeff;color:#0b5cab}.pill.success{background:#dcf6e5;color:#146b35}.pill.warning{background:#fff0c9;color:#835500}.pill.danger{background:#ffe2df;color:#a52a22}\n        table{width:100%;border-collapse:collapse}th,td{padding:10px;border:1px solid #dce5ed;text-align:left;vertical-align:top}th{background:#edf5fb}\n        .btn{display:inline-flex;padding:10px 15px;border-radius:9px;background:#e9f0f6;color:#17324d;text-decoration:none;font-weight:800}\n        .notice{padding:14px;border-radius:12px;background:#fff7df;border:1px solid #efcf7d;line-height:1.5}\n        @media(max-width:700px){.grid{grid-template-columns:1fr}}\n    </style>\n</head>\n<body>\n{% include "partials/dropdown_menu_v1.html" %}\n<header class="hero">\n    <div class="hero-inner">\n        <div style="font-size:13px;font-weight:800">KẾT QUẢ TIẾP NHẬN FILE</div>\n        <h1 style="margin:7px 0">{{ job.job_code }}</h1>\n        <span class="pill {{ status_class }}">{{ status_label }}</span>\n    </div>\n</header>\n<main class="wrap">\n    <section class="panel">\n        <div class="notice">\n            <strong>Lưu ý V1A:</strong> “Đã nhận/Đã kiểm tra” nghĩa là máy chủ đã nhận và lưu file an toàn.\n            Chưa đồng nghĩa với “Đã cập nhật dữ liệu hộ dân”. Việc ghi CSDL chỉ thực hiện ở bước V1B sau khi\n            bộ ánh xạ mẫu chính thức kiểm tra đủ dòng/cột và xung đột.\n        </div>\n    </section>\n    <section class="panel">\n        <h2 style="margin-top:0">Thông tin lần gửi</h2>\n        <div class="grid">\n            <div class="item"><strong>File:</strong> {{ job.original_file_name }}</div>\n            <div class="item"><strong>Thời gian nhận:</strong> {{ job.received_at.strftime(\'%d/%m/%Y %H:%M:%S\') if job.received_at else \'\' }}</div>\n            <div class="item"><strong>Người gửi:</strong> {{ job.actor_name_snapshot or \'\' }}</div>\n            <div class="item"><strong>Đơn vị:</strong> {{ job.actor_unit_snapshot or \'\' }}</div>\n            <div class="item"><strong>Năm học:</strong> {{ batch.school_year.code if batch else \'\' }}</div>\n            <div class="item"><strong>Xã/phường:</strong> {{ batch.commune.name if batch else \'\' }}</div>\n            <div class="item"><strong>Kích thước:</strong> {{ \'%.1f\'|format(job.file_size / 1024) }} KB</div>\n            <div class="item"><strong>SHA256:</strong> <span style="word-break:break-all">{{ job.sha256 or \'\' }}</span></div>\n            <div class="item"><strong>Macro/VBA:</strong> {{ \'Có dấu hiệu\' if job.has_macro else \'Không phát hiện\' }}</div>\n            <div class="item"><strong>File trùng với:</strong> {{ job.duplicate_of_job_code or \'Không\' }}</div>\n        </div>\n        <p><strong>Thông báo:</strong> {{ job.message or \'\' }}</p>\n        {% if sheet_names %}\n        <p><strong>Sheet phát hiện:</strong> {{ sheet_names|join(\', \') }}</p>\n        {% endif %}\n    </section>\n    <section class="panel">\n        <h2 style="margin-top:0">Lỗi / khuyến cáo</h2>\n        <table>\n            <thead><tr><th>Mức</th><th>Sheet</th><th>Dòng</th><th>Cột</th><th>Mã lỗi</th><th>Nội dung</th></tr></thead>\n            <tbody>\n            {% for item in errors %}\n                <tr>\n                    <td>{{ item.severity }}</td><td>{{ item.sheet_name or \'—\' }}</td><td>{{ item.row_number or \'—\' }}</td>\n                    <td>{{ item.column_name or \'—\' }}</td><td>{{ item.error_code or \'—\' }}</td><td>{{ item.message }}</td>\n                </tr>\n            {% else %}\n                <tr><td colspan="6">Không có lỗi/khuyến cáo được ghi nhận ở bước kiểm tra hiện tại.</td></tr>\n            {% endfor %}\n            </tbody>\n        </table>\n    </section>\n    <a class="btn" href="/dieu-tra/cap-nhat-ho-dan?batch_id={{ job.survey_batch_id }}">← Quay về Cập nhật dữ liệu hộ dân</a>\n</main>\n</body>\n</html>\n',
    "app/templates/surveys/household_statistics_v1.html": '<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Thống kê hộ dân</title>\n    <link rel="stylesheet" href="/static/css/style.css">\n    <style>\n        *{box-sizing:border-box}body{margin:0;background:#eef4f9;color:#17324d;font-family:Arial,sans-serif}.hero{background:#0f5fa8;color:#fff;padding:25px 3vw}.wrap,.hero-inner{max-width:1400px;margin:auto}.wrap{padding:22px 3vw 48px}\n        .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,.panel{background:#fff;border:1px solid #d8e4ef;border-radius:15px;padding:17px;box-shadow:0 6px 18px rgba(23,50,77,.05)}\n        .card span{display:block;font-size:12px;font-weight:800;color:#64798c}.card strong{display:block;font-size:28px;color:#0f5fa8;margin-top:7px}\n        .grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:16px}.panel h2{margin-top:0}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #e6edf3;text-align:left}th{background:#edf5fb}\n        .note{background:#fff7df;border:1px solid #efcf7d;border-radius:12px;padding:14px;margin-bottom:16px;line-height:1.5}.btn{display:inline-flex;padding:10px 15px;border-radius:9px;background:#fff;color:#17324d;text-decoration:none;font-weight:800}\n        @media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:520px){.cards{grid-template-columns:1fr}}\n    </style>\n</head>\n<body>\n{% include "partials/dropdown_menu_v1.html" %}\n<header class="hero"><div class="hero-inner">\n    <div style="font-size:13px;font-weight:800">THỐNG KÊ HỘ DÂN VÀ CÁC YẾU TỐ LIÊN QUAN</div>\n    <h1 style="margin:7px 0">{{ batch.name }}</h1>\n    <p>{{ batch.commune.name }} · {{ batch.school_year.code }} · {{ scope_label }}</p>\n    <a class="btn" href="/dieu-tra/cap-nhat-ho-dan?batch_id={{ batch.id }}">← Cập nhật dữ liệu hộ dân</a>\n</div></header>\n<main class="wrap">\n    <div class="note">\n        Tuổi tính tại {{ reference_date.strftime(\'%d/%m/%Y\') }}. Phổ cập: 0–18 tuổi; Xóa mù chữ: 18–60 tuổi;\n        người 18 tuổi được tính ở cả hai nhóm. Cấp học được suy ra từ trường/lớp hiện có, không theo cấp của giáo viên.\n    </div>\n    <section class="cards">\n        <div class="card"><span>TỔNG HỘ</span><strong>{{ total_households }}</strong></div>\n        <div class="card"><span>TỔNG THÀNH VIÊN</span><strong>{{ total_people }}</strong></div>\n        <div class="card"><span>PHỔ CẬP 0–18</span><strong>{{ total_pcgd }}</strong></div>\n        <div class="card"><span>XMC 18–60</span><strong>{{ total_xmc }}</strong></div>\n        <div class="card"><span>ĐÚNG 18 TUỔI</span><strong>{{ total_age_18 }}</strong></div>\n        <div class="card"><span>THIẾU SỐ ĐỊNH DANH</span><strong>{{ missing_personal_id }}</strong></div>\n        <div class="card"><span>THIẾU CCCD</span><strong>{{ missing_citizen_id }}</strong></div>\n        <div class="card"><span>THIẾU DỮ LIỆU NĂM HỌC</span><strong>{{ missing_year_record }}</strong></div>\n    </section>\n    <section class="grid">\n        <article class="panel"><h2>Nhóm/cấp học</h2><table><thead><tr><th>Nhóm</th><th>Số người</th></tr></thead><tbody>\n        {% for code,label in level_labels.items() %}<tr><td>{{ label }}</td><td><strong>{{ level_counts.get(code,0) }}</strong></td></tr>{% endfor %}\n        </tbody></table></article>\n        <article class="panel"><h2>Trạng thái phiếu</h2><table><thead><tr><th>Trạng thái</th><th>Số phiếu</th></tr></thead><tbody>\n        {% for code,label in form_status_labels.items() %}<tr><td>{{ label }}</td><td><strong>{{ form_status_counts.get(code,0) }}</strong></td></tr>{% endfor %}\n        </tbody></table></article>\n        <article class="panel"><h2>Tình trạng học tập</h2><table><thead><tr><th>Tình trạng</th><th>Số người</th></tr></thead><tbody>\n        {% for code,label in learning_labels.items() %}<tr><td>{{ label }}</td><td><strong>{{ learning_counts.get(code,0) }}</strong></td></tr>{% endfor %}\n        </tbody></table></article>\n        <article class="panel"><h2>Cư trú</h2><table><thead><tr><th>Trạng thái</th><th>Số người</th></tr></thead><tbody>\n        {% for code,label in residency_labels.items() %}<tr><td>{{ label }}</td><td><strong>{{ residency_counts.get(code,0) }}</strong></td></tr>{% endfor %}\n        </tbody></table></article>\n    </section>\n</main>\n</body>\n</html>\n',
    "app/templates/surveys/field_print.html": '<!DOCTYPE html>\n<html lang="vi">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Phiếu điều tra phổ cập giáo dục - xóa mù chữ</title>\n    <style>\n        :root{--ink:#111;--line:#333;--soft:#f2f2f2;--blue:#125fb8}\n        *{box-sizing:border-box}\n        body{margin:0;background:#e7edf3;color:var(--ink);font-family:"Times New Roman",serif;font-size:10px}\n        .toolbar{position:sticky;top:0;z-index:20;background:var(--blue);color:#fff;padding:10px 18px;display:flex;justify-content:space-between;gap:12px;align-items:center}\n        .toolbar-actions{display:flex;gap:8px;flex-wrap:wrap}\n        .button{display:inline-block;padding:8px 12px;border:0;border-radius:7px;background:#fff;color:#173b63;font-weight:700;text-decoration:none;cursor:pointer;font-family:Arial,sans-serif}\n        .note{width:287mm;margin:10px auto;padding:9px 12px;background:#fff7df;border:1px solid #e2c36c;font-family:Arial,sans-serif;font-size:12px}\n        .sheet{width:287mm;min-height:200mm;margin:8mm auto;padding:4mm;background:#fff;box-shadow:0 2px 12px rgba(0,0,0,.15);page-break-after:always}\n        .sheet:last-child{page-break-after:auto}\n        .cover-title{text-align:center;font-size:18px;font-weight:700;text-transform:uppercase;margin:5mm 0}\n        .meta-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm 8mm;font-size:11px;margin-bottom:4mm}\n        .manifest{width:100%;border-collapse:collapse;font-size:10px}\n        .manifest th,.manifest td{border:1px solid #333;padding:2mm}\n        .manifest th{background:#eee}\n        .form-head{display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:3mm;align-items:start;margin-bottom:2mm}\n        .left-info,.right-info{line-height:1.55;font-size:9px}\n        .main-title{text-align:center}\n        .main-title h1{font-size:14px;margin:1mm 0;text-transform:uppercase}\n        .main-title div{font-size:9px}\n        .line{display:inline-block;min-width:38mm;border-bottom:1px dotted #333}\n        .official{width:100%;border-collapse:collapse;table-layout:fixed;font-size:6.8px;line-height:1.08}\n        .official th,.official td{border:1px solid #222;padding:.7mm;vertical-align:top;overflow-wrap:anywhere}\n        .official th{text-align:center;font-weight:700;background:#f4f4f4}\n        .official .c-stt{width:6mm}.official .c-person{width:38mm}.official .c-class{width:31mm}.official .c-school{width:43mm}\n        .official .c-complete{width:30mm}.official .c-finished{width:17mm}.official .c-drop{width:17mm}.official .c-xmc{width:20mm}\n        .official .c-disability{width:20mm}.official .c-move{width:24mm}.official .c-note{width:22mm}\n        .person-cell{min-height:19mm}\n        .person-name{font-size:7.5px;font-weight:700;margin-bottom:.6mm}\n        .person-line{min-height:2.15mm;border-bottom:1px dotted #aaa;padding:.15mm 0}\n        .year-line{min-height:2.45mm;border-bottom:1px dotted #bbb;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n        .year-code{display:inline-block;width:13mm;font-weight:700}\n        .center{text-align:center}\n        .page-caption{text-align:right;font-size:8px;margin-top:1mm}\n        .signature-row{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:7mm;text-align:center;margin-top:3mm;font-size:9px;page-break-inside:avoid}\n        .signature-box{min-height:18mm}\n        .footer{display:flex;justify-content:space-between;margin-top:1.5mm;font-size:7.5px;color:#555}\n        .blank-dots{letter-spacing:.04em}\n        @page{size:A4 landscape;margin:4mm}\n        @media print{\n            body{background:#fff}\n            .toolbar,.note{display:none!important}\n            .sheet{width:auto;min-height:auto;margin:0;padding:0;box-shadow:none;break-after:page}\n            .sheet:last-child{break-after:auto}\n        }\n    </style>\n</head>\n<body>\n<div class="toolbar">\n    <div>\n        <strong>Phiếu điều tra PCGD - XMC · A4 nằm ngang</strong><br>\n        {{ batch.commune.name }} · {{ batch.school_year.code }} · {{ form_total }} phiếu\n    </div>\n    <div class="toolbar-actions">\n        <a class="button" href="/dieu-tra/trung-tam-phieu?school_year_id={{ batch.school_year.id }}">← Trung tâm phiếu</a>\n        <a class="button" href="/dieu-tra/cap-nhat-ho-dan/mau-phieu-dieu-tra">Mẫu gốc</a>\n        <button class="button" type="button" onclick="window.print()">🖨️ In / Lưu PDF</button>\n    </div>\n</div>\n\n<div class="note">\n    Bản in được bố trí theo mẫu <strong>PHIẾU ĐIỀU TRA PHỔ CẬP GIÁO DỤC - CHỐNG MÙ CHỮ</strong>,\n    khổ <strong>A4 nằm ngang</strong>. Mỗi trang tối đa 7 thành viên. Hộ có trên 7 thành viên tự động tạo\n    trang tiếp theo cùng số phiếu để không phải thu nhỏ chữ quá mức.\n</div>\n\n<section class="sheet">\n    <div class="cover-title">Bảng kê giao nhận phiếu điều tra</div>\n    <div class="meta-grid">\n        <div><strong>Đợt:</strong> {{ batch.name }}</div>\n        <div><strong>Năm học:</strong> {{ batch.school_year.code }}</div>\n        <div><strong>Xã/phường:</strong> {{ batch.commune.name }}</div>\n        <div><strong>Mã đợt:</strong> {{ batch.code }}</div>\n        <div><strong>Tổng phiếu:</strong> {{ form_total }}</div>\n        <div><strong>Tổng thành viên:</strong> {{ person_total }}</div>\n    </div>\n    <table class="manifest">\n        <thead><tr><th>STT</th><th>Số phiếu</th><th>Mã hộ</th><th>Chủ hộ</th><th>Thôn/xóm</th><th>Số người</th><th>Người điều tra</th><th>Ký nhận</th></tr></thead>\n        <tbody>\n        {% for row in form_rows %}\n        <tr>\n            <td class="center">{{ loop.index }}</td>\n            <td>{{ row.form.form_number }}</td>\n            <td>{{ row.household.code }}</td>\n            <td>{{ row.household.head_name }}</td>\n            <td>{{ row.household.hamlet_name or \'\' }}</td>\n            <td class="center">{{ row.people|length }}</td>\n            <td>{{ row.investigator_names|join(\', \') }}</td>\n            <td></td>\n        </tr>\n        {% endfor %}\n        </tbody>\n    </table>\n    <div class="signature-row" style="margin-top:8mm">\n        <div class="signature-box"><strong>NGƯỜI GIAO PHIẾU</strong><br><em>(Ký, ghi rõ họ tên)</em></div>\n        <div class="signature-box"><strong>NGƯỜI NHẬN PHIẾU</strong><br><em>(Ký, ghi rõ họ tên)</em></div>\n        <div class="signature-box"></div>\n        <div class="signature-box"><strong>ĐẠI DIỆN XÃ/PHƯỜNG</strong><br><em>(Ký, đóng dấu)</em></div>\n    </div>\n</section>\n\n{% for row in form_rows %}\n    {% set row_loop = loop %}\n    {% for people_page in row.pages %}\n    {% set page_loop = loop %}\n    <section class="sheet">\n        <div class="form-head">\n            <div class="left-info">\n                <div><strong>Phường/Xã (1):</strong> {{ batch.commune.name }}</div>\n                <div><strong>Tổ, thôn, xóm (2):</strong> {{ row.household.hamlet_name or \'................................\' }}</div>\n                <div><strong>Địa chỉ (3):</strong> {{ row.household.address or \'................................\' }}</div>\n            </div>\n            <div class="main-title">\n                <h1>Phiếu điều tra phổ cập giáo dục - chống mù chữ</h1>\n                <div>Năm học {{ batch.school_year.code }}</div>\n                {% if page_loop.length > 1 %}\n                <div><strong>Trang {{ page_loop.index }}/{{ page_loop.length }}</strong></div>\n                {% endif %}\n            </div>\n            <div class="right-info">\n                <div><strong>Họ và tên chủ hộ (4):</strong> {{ row.household.head_name }}</div>\n                <div><strong>Số phiếu (5):</strong> {{ row.form.form_number }}</div>\n                <div><strong>Diện cư trú (6):</strong> □ Thường trú &nbsp; □ Tạm trú</div>\n                <div><strong>Điện thoại (7):</strong> {{ row.household.phone or \'........................\' }}</div>\n            </div>\n        </div>\n\n        <table class="official">\n            <thead>\n                <tr>\n                    <th class="c-stt">STT</th>\n                    <th class="c-person">HỌ VÀ TÊN ĐỐI TƯỢNG<br><span style="font-weight:400">(Lớn tuổi ghi trước)</span></th>\n                    <th class="c-class">TÊN LỚP ĐANG HỌC<br><span style="font-weight:400">(Theo năm học)</span></th>\n                    <th class="c-school">TÊN TRƯỜNG - HUYỆN ĐANG HỌC<br><span style="font-weight:400">(Tương ứng từng năm học)</span></th>\n                    <th class="c-complete">TỐT NGHIỆP / HOÀN THÀNH<br><span style="font-weight:400">MN → THPT · Bổ túc · TN nghề</span></th>\n                    <th class="c-finished">HỌC XONG<br><span style="font-weight:400">Lớp / Năm</span></th>\n                    <th class="c-drop">BỎ HỌC<br><span style="font-weight:400">Lớp / Năm</span></th>\n                    <th class="c-xmc">MÙ CHỮ<br><span style="font-weight:400">Học XMC / CN XMC / Tái mù</span></th>\n                    <th class="c-disability">KHUYẾT TẬT</th>\n                    <th class="c-move">CHUYỂN ĐẾN, CHUYỂN ĐI, CHẾT</th>\n                    <th class="c-note">GHI CHÚ</th>\n                </tr>\n            </thead>\n            <tbody>\n            {% for item in people_page %}\n                <tr>\n                {% if item %}\n                    <td class="center">{{ (page_loop.index0 * 7) + loop.index }}</td>\n                    <td class="person-cell">\n                        <div class="person-name">{{ item.person.full_name }}</div>\n                        <div class="person-line"><strong>QH chủ hộ:</strong> {{ item.person.relationship_to_head or \'\' }}</div>\n                        <div class="person-line"><strong>Sinh:</strong> {{ item.date_of_birth or \'\' }}</div>\n                        <div class="person-line"><strong>Nữ:</strong> {% if item.person.gender == \'Nữ\' %}☒{% else %}☐{% endif %} &nbsp; <strong>DT:</strong> {{ item.person.ethnic_group or \'\' }}</div>\n                        <div class="person-line"><strong>TG:</strong> ................................</div>\n                        <div class="person-line"><strong>Cha, mẹ/Ng. đỡ đầu:</strong> {{ item.parent_name or \'\' }}</div>\n                        <div class="person-line"><strong>Mã nội bộ:</strong> {{ item.person.code }}</div>\n                    </td>\n                    <td>\n                        {% for y in item.year_rows %}\n                        <div class="year-line"><span class="year-code">{{ y.year_code }}</span>{{ y.class_name or \'\' }}</div>\n                        {% endfor %}\n                        {% for _ in range(7 - item.year_rows|length) %}\n                        <div class="year-line"><span class="year-code">20__-20__</span></div>\n                        {% endfor %}\n                    </td>\n                    <td>\n                        {% for y in item.year_rows %}\n                        <div class="year-line"><span class="year-code">{{ y.year_code }}</span>{{ y.school_name or \'\' }}</div>\n                        {% endfor %}\n                        {% for _ in range(7 - item.year_rows|length) %}\n                        <div class="year-line"><span class="year-code">20__-20__</span></div>\n                        {% endfor %}\n                    </td>\n                    <td>{{ item.completion_text or \'\' }}</td>\n                    <td>{{ item.study_completed_text or \'\' }}</td>\n                    <td>{{ item.dropout_text or \'\' }}</td>\n                    <td>{{ item.literacy_text or \'\' }}</td>\n                    <td>{{ item.disability_text or \'\' }}</td>\n                    <td>{{ item.movement_text or \'\' }}</td>\n                    <td>{{ item.notes_text or \'\' }}</td>\n                {% else %}\n                    <td class="center">{{ (page_loop.index0 * 7) + loop.index }}</td>\n                    <td class="person-cell">\n                        <div class="person-name">................................................</div>\n                        <div class="person-line"><strong>QH chủ hộ:</strong></div>\n                        <div class="person-line"><strong>Sinh:</strong></div>\n                        <div class="person-line"><strong>Nữ:</strong> ☐ &nbsp; <strong>DT:</strong></div>\n                        <div class="person-line"><strong>TG:</strong></div>\n                        <div class="person-line"><strong>Cha, mẹ/Ng. đỡ đầu:</strong></div>\n                        <div class="person-line"><strong>Mã:</strong></div>\n                    </td>\n                    <td>{% for _ in range(7) %}<div class="year-line"><span class="year-code">20__-20__</span></div>{% endfor %}</td>\n                    <td>{% for _ in range(7) %}<div class="year-line"><span class="year-code">20__-20__</span></div>{% endfor %}</td>\n                    <td></td><td></td><td></td><td></td><td></td><td></td><td></td>\n                {% endif %}\n                </tr>\n            {% endfor %}\n            </tbody>\n        </table>\n\n        {% if page_loop.last %}\n        <div class="signature-row">\n            <div class="signature-box"><strong>HỌ, TÊN CHỦ HỘ</strong><br><br><em>(Ký, ghi rõ họ tên)</em></div>\n            <div class="signature-box"><strong>CÁN BỘ, NHÂN VIÊN ĐIỀU TRA 1</strong><br>{{ row.investigator_names[0] if row.investigator_names|length > 0 else \'\' }}<br><em>(Ký, ghi rõ họ tên)</em></div>\n            <div class="signature-box"><strong>CÁN BỘ, NHÂN VIÊN ĐIỀU TRA 2</strong><br>{{ row.investigator_names[1] if row.investigator_names|length > 1 else \'\' }}<br><em>(Ký, ghi rõ họ tên)</em></div>\n            <div class="signature-box"><strong>XÁC NHẬN CỦA UBND PHƯỜNG/XÃ</strong><br><br><em>(Ký tên, đóng dấu)</em></div>\n        </div>\n        {% endif %}\n        <div class="footer">\n            <span>{{ batch.code }} · {{ row.form.form_number }} · {{ row.household.code }}</span>\n            <span>In lúc {{ generated_at.strftime(\'%d/%m/%Y %H:%M\') }}</span>\n        </div>\n    </section>\n    {% endfor %}\n{% endfor %}\n</body>\n</html>\n',
}

XLS_GZIP_B64 = ''
XLSX_GZIP_B64 = ''
XLS_SHA256 = '50e5ccb75c0e4306be60b431bef38226a57dc16bb0144d167e783685da34bf87'
XLSX_SHA256 = '2ab1d479bbafb5519aee7b9a13d261fb8bca1e85391a6f5fa83e415d963f599e'

PATCH_FILES = [
    "app/main.py",
    "app/access_control.py",
    "app/templates/partials/dropdown_menu_v1.html",
    "app/routers/survey_print.py",
]
NEW_OR_REPLACED_FILES = list(FILES.keys()) + [
    "app/reference/bai_13b_9/pcgd_nhapphieudieutra_2025.xls",
    "app/reference/bai_13b_9/mau-phieu-dieu-tra-pho-cap-giao-duc-xoa-mu-chu.xlsx",
]
ALL_FILES = PATCH_FILES + NEW_OR_REPLACED_FILES

MARK_MAIN = "BAI_13B_9_V1A_HOUSEHOLD_UPDATE_ROUTER"
MARK_ACCESS = "BAI_13B_9_V1A_ACCESS"
MARK_MENU = "BAI_13B_9_V1A_MENU"
MARK_PRINT = "BAI_13B_9_V1A_OFFICIAL_PRINT"


def _read(rel: str) -> str:
    path = PROJECT / rel
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def _write(rel: str, text_value: str) -> None:
    path = PROJECT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text_value, encoding="utf-8")


def _db_path() -> Path:
    sys.path.insert(0, str(PROJECT))
    old = Path.cwd()
    try:
        os.chdir(PROJECT)
        from app.database import DATABASE_PATH
        return Path(DATABASE_PATH)
    finally:
        os.chdir(old)
        try:
            sys.path.remove(str(PROJECT))
        except ValueError:
            pass


def _backup_files(db_path: Path) -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []

    for rel in ALL_FILES:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    if db_path.exists():
        db_rel = "database/" + db_path.name
        dst = BACKUP / db_rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(db_path, dst)
        manifest.append({
            "path": str(db_path),
            "database": True,
            "backup": db_rel,
            "existed": True,
        })

    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def _restore(manifest: list[dict], db_path: Path) -> None:
    for item in reversed(manifest):
        if item.get("database"):
            src = BACKUP / item["backup"]
            if src.exists():
                shutil.copy2(src, db_path)
            continue

        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def _patch_main(text_value: str) -> str:
    if MARK_MAIN in text_value:
        return text_value

    import_anchor = (
        "from app.routers.survey_print import router as survey_print_router\n"
    )
    if import_anchor not in text_value:
        raise RuntimeError(
            "app/main.py không có survey_print_router. "
            "Dừng để không sửa nhầm phiên bản."
        )

    import_line = (
        "from app.routers.household_updates import "
        "router as household_updates_router  "
        "# BAI_13B_9_V1A_HOUSEHOLD_UPDATE_ROUTER\n"
    )
    text_value = text_value.replace(
        import_anchor,
        import_anchor + import_line,
        1,
    )

    include_anchor = "app.include_router(survey_print_router)\n"
    if include_anchor not in text_value:
        raise RuntimeError(
            "Không tìm thấy vị trí include survey_print_router."
        )
    text_value = text_value.replace(
        include_anchor,
        include_anchor
        + "app.include_router(household_updates_router)\n",
        1,
    )
    return text_value


def _patch_access(text_value: str) -> str:
    if MARK_ACCESS in text_value:
        return text_value

    action_anchor = (
        "        # Bài 12D-14A: Sở và xã/phường được cập nhật dữ liệu lịch sử.\n"
    )
    if action_anchor not in text_value:
        raise RuntimeError(
            "access_control.py thiếu điểm chèn quyền thao tác."
        )

    action_block = """        # === BAI_13B_9_V1A_ACCESS_ACTION_START ===
        is_household_update_center = (
            normalized_path.startswith("/dieu-tra/cap-nhat-ho-dan")
        )
        is_household_update_batch = bool(
            re.match(
                r"^/dieu-tra/\\d+/cap-nhat-ho-dan(?:/|$)",
                normalized_path,
            )
        )
        if is_household_update_center or is_household_update_batch:
            allowed_roles = {
                *ADMIN_ROLE_CODES,
                DEPARTMENT_ROLE_CODE,
                COMMUNE_ROLE_CODE,
                SCHOOL_ROLE_CODE,
            }
            if role_code not in allowed_roles:
                return False
            if method in SAFE_METHODS:
                return True
            return (
                role_code in ADMIN_ROLE_CODES
                or role_code == COMMUNE_ROLE_CODE
                or role_code == SCHOOL_ROLE_CODE
            )
        # === BAI_13B_9_V1A_ACCESS_ACTION_END ===

"""
    text_value = text_value.replace(
        action_anchor,
        action_block + action_anchor,
        1,
    )

    scope_anchor = (
        "        # Bài 12D-14A: Trung tâm dữ liệu lịch sử dùng URL chung,\n"
    )
    if scope_anchor not in text_value:
        raise RuntimeError(
            "access_control.py thiếu điểm chèn phạm vi Điều tra."
        )

    scope_block = """        # === BAI_13B_9_V1A_ACCESS_SCOPE_START ===
        if normalized_path.startswith("/dieu-tra/cap-nhat-ho-dan"):
            return role_code in {
                COMMUNE_ROLE_CODE,
                SCHOOL_ROLE_CODE,
            }
        # ADMIN/Sở và PHONG_BAN đã được cho qua ở đầu hàm.
        # === BAI_13B_9_V1A_ACCESS_SCOPE_END ===

"""
    text_value = text_value.replace(
        scope_anchor,
        scope_block + scope_anchor,
        1,
    )

    lock_func_pos = text_value.find(
        "def _kiem_tra_khoa_dot_dieu_tra"
    )
    if lock_func_pos < 0:
        raise RuntimeError("Không tìm thấy hàm kiểm tra khóa đợt.")

    lock_anchor = "        batch_id = int(batch_match.group(\"batch_id\"))\n"
    pos = text_value.find(lock_anchor, lock_func_pos)
    if pos < 0:
        raise RuntimeError(
            "Không tìm thấy batch_id trong hàm kiểm tra khóa."
        )
    pos_end = pos + len(lock_anchor)
    lock_block = """
        # === BAI_13B_9_V1A_ACCESS_LOCK_START ===
        # V1A chỉ tiếp nhận vào vùng chờ, chưa ghi dữ liệu hộ dân.
        # Cho router nhận file để trả trạng thái rõ ràng kể cả khi đợt khóa.
        if normalized_path == (
            f"/dieu-tra/{batch_id}/cap-nhat-ho-dan/gui-file"
        ):
            return None
        # === BAI_13B_9_V1A_ACCESS_LOCK_END ===
"""
    text_value = (
        text_value[:pos_end]
        + lock_block
        + text_value[pos_end:]
    )
    return text_value


def _patch_menu(text_value: str) -> str:
    if MARK_MENU in text_value:
        return text_value

    trigger = text_value.find("2. Điều tra hộ dân")
    if trigger < 0:
        raise RuntimeError(
            "Không tìm thấy menu 2. Điều tra hộ dân."
        )

    dropdown = text_value.find(
        '<div class="pc-dropdown"',
        trigger,
    )
    if dropdown < 0:
        raise RuntimeError(
            "Không tìm thấy dropdown của Điều tra hộ dân."
        )
    open_end = text_value.find(">", dropdown)
    if open_end < 0:
        raise RuntimeError(
            "Không xác định được điểm chèn menu."
        )

    block = """
                    {# === BAI_13B_9_V1A_MENU === #}
                    {% if nguoi_dung and nguoi_dung.role_code != 'GIAO_VIEN' %}
                    <a
                        href="/dieu-tra/cap-nhat-ho-dan"
                        role="menuitem"
                    >
                        Cập nhật dữ liệu hộ dân
                    </a>
                    {% endif %}
"""
    return (
        text_value[:open_end + 1]
        + block
        + text_value[open_end + 1:]
    )


def _patch_survey_print(text_value: str) -> str:
    if MARK_PRINT in text_value:
        return text_value

    required = [
        'name="surveys/field_print.html"',
        "record_by_person_id = {",
        "person_total += len(people_rows)",
    ]
    for marker in required:
        if marker not in text_value:
            raise RuntimeError(
                f"survey_print.py thiếu nền cần thiết: {marker}"
            )

    eager_anchor = (
        "                selectinload(SurveyForm.person_year_records)\n"
        "                .selectinload(SurveyPersonYearRecord.classroom),\n"
    )
    if eager_anchor in text_value and (
        "selectinload(SurveyPersonYearRecord.school_year)"
        not in text_value
    ):
        text_value = text_value.replace(
            eager_anchor,
            eager_anchor
            + "                selectinload(SurveyForm.person_year_records)\n"
              "                .selectinload(SurveyPersonYearRecord.school_year),\n",
            1,
        )

    pattern = re.compile(
        r"        record_by_person_id = \{.*?"
        r"        person_total \+= len\(people_rows\)\n",
        re.S,
    )
    replacement = (
        "        # === BAI_13B_9_V1A_OFFICIAL_PRINT_START ===\n"
        + '        records_by_person_id: dict[int, list[SurveyPersonYearRecord]] = {}\n        for record_item in survey_form.person_year_records:\n            records_by_person_id.setdefault(\n                record_item.survey_person_id,\n                [],\n            ).append(record_item)\n\n        people_rows: list[dict[str, Any]] = []\n\n        for person in sorted(\n            (\n                item\n                for item in survey_form.household.people\n                if item.is_active\n            ),\n            key=lambda item: (\n                item.date_of_birth is None,\n                item.date_of_birth or datetime.max.date(),\n                item.full_name,\n            ),\n        ):\n            person_records = sorted(\n                records_by_person_id.get(person.id, []),\n                key=lambda item: (\n                    (\n                        item.school_year.code\n                        if item.school_year is not None\n                        else ""\n                    ),\n                    item.school_year_id,\n                    item.id,\n                ),\n            )\n            record = next(\n                (\n                    item\n                    for item in reversed(person_records)\n                    if item.school_year_id == batch.school_year_id\n                ),\n                None,\n            )\n\n            year_rows = [\n                {\n                    "year_code": (\n                        item.school_year.code\n                        if item.school_year is not None\n                        else str(item.school_year_id)\n                    ),\n                    "school_name": ten_truong(item),\n                    "class_name": ten_lop(item),\n                    "learning_status": LEARNING_STATUS_LABELS.get(\n                        item.learning_status,\n                        item.learning_status or "",\n                    ),\n                }\n                for item in person_records[-7:]\n            ]\n\n            completion_parts: list[str] = []\n            for item in person_records:\n                if item.completed_preschool_5 is True:\n                    year_code = (\n                        item.school_year.code\n                        if item.school_year is not None\n                        else ""\n                    )\n                    completion_parts.append(\n                        "MN" + (f" · {year_code}" if year_code else "")\n                    )\n\n            study_completed = next(\n                (\n                    item\n                    for item in reversed(person_records)\n                    if item.learning_status\n                    in {"HOC_XONG", "DA_HOC_XONG"}\n                ),\n                None,\n            )\n            dropout = next(\n                (\n                    item\n                    for item in reversed(person_records)\n                    if item.learning_status in {"BO_HOC", "THOI_HOC"}\n                ),\n                None,\n            )\n\n            def _record_short(item):\n                if item is None:\n                    return ""\n                class_name = ten_lop(item)\n                year_code = (\n                    item.school_year.code\n                    if item.school_year is not None\n                    else ""\n                )\n                values = [value for value in (class_name, year_code) if value]\n                return " · ".join(values)\n\n            special_text = str(person.special_circumstances or "")\n            special_lower = special_text.lower()\n            disability_text = (\n                special_text\n                if (\n                    "khuyết" in special_lower\n                    or "khuyet" in special_lower\n                    or "tật" in special_lower\n                    or "tat " in special_lower\n                )\n                else ""\n            )\n\n            movement_text = ""\n            if person.residency_status in {"CHUYEN_DEN", "CHUYEN_DI"}:\n                movement_text = RESIDENCY_STATUS_LABELS.get(\n                    person.residency_status,\n                    person.residency_status,\n                )\n\n            parent_names = [\n                value\n                for value in (\n                    person.father_name,\n                    person.mother_name,\n                )\n                if value\n            ]\n\n            people_rows.append(\n                {\n                    "person": person,\n                    "record": record,\n                    "date_of_birth": dinh_dang_ngay(\n                        person.date_of_birth\n                    ),\n                    "residency_label": RESIDENCY_STATUS_LABELS.get(\n                        person.residency_status,\n                        person.residency_status or "Chưa xác định",\n                    ),\n                    "learning_label": (\n                        "Chưa xác định"\n                        if record is None\n                        else LEARNING_STATUS_LABELS.get(\n                            record.learning_status,\n                            (\n                                "Chưa xác định"\n                                if record.learning_status\n                                == "CHUA_XAC_DINH"\n                                else record.learning_status\n                            ),\n                        )\n                    ),\n                    "school_name": ten_truong(record),\n                    "class_name": ten_lop(record),\n                    "year_rows": year_rows,\n                    "completion_text": ", ".join(completion_parts[-3:]),\n                    "study_completed_text": _record_short(study_completed),\n                    "dropout_text": _record_short(dropout),\n                    "literacy_text": "",\n                    "disability_text": disability_text,\n                    "movement_text": movement_text,\n                    "notes_text": str(person.notes or ""),\n                    "parent_name": " / ".join(parent_names),\n                    "citizen_id": getattr(person, "citizen_id", None) or "",\n                    "indicator_values": (\n                        []\n                        if record is None\n                        else [\n                            BOOLEAN_LABELS[record.completed_preschool_5],\n                            BOOLEAN_LABELS[record.attends_required_days],\n                            BOOLEAN_LABELS[record.attends_regularly],\n                            BOOLEAN_LABELS[record.prepared_vietnamese],\n                            BOOLEAN_LABELS[record.weight_monitored],\n                            BOOLEAN_LABELS[record.underweight],\n                            BOOLEAN_LABELS[record.height_monitored],\n                            BOOLEAN_LABELS[record.stunted],\n                        ]\n                    ),\n                }\n            )\n\n        person_total += len(people_rows)\n        people_pages = [\n            people_rows[index:index + 7]\n            for index in range(0, len(people_rows), 7)\n        ] or [[]]\n        people_pages = [\n            page + [None] * (7 - len(page))\n            for page in people_pages\n        ]\n'
        + "        # === BAI_13B_9_V1A_OFFICIAL_PRINT_END ===\n"
    )
    text_value, count = pattern.subn(
        lambda match: replacement,
        text_value,
        count=1,
    )
    if count != 1:
        raise RuntimeError(
            "Không thay được khối tạo dữ liệu người trong survey_print.py."
        )

    pages_anchor = '                "people": people_rows,\n'
    if pages_anchor not in text_value:
        raise RuntimeError(
            "Không tìm thấy context people của form_rows."
        )
    text_value = text_value.replace(
        pages_anchor,
        pages_anchor + '                "pages": people_pages,\n',
        1,
    )
    return text_value


def _write_reference_files() -> None:
    ref = APP / "reference" / "bai_13b_9"
    ref.mkdir(parents=True, exist_ok=True)

    xls = gzip.decompress(base64.b64decode(XLS_GZIP_B64))
    xlsx = gzip.decompress(base64.b64decode(XLSX_GZIP_B64))

    if hashlib.sha256(xls).hexdigest() != XLS_SHA256:
        raise RuntimeError("Checksum mẫu .xls đóng gói không đúng.")
    if hashlib.sha256(xlsx).hexdigest() != XLSX_SHA256:
        raise RuntimeError("Checksum mẫu phiếu .xlsx đóng gói không đúng.")

    (ref / "pcgd_nhapphieudieutra_2025.xls").write_bytes(xls)
    (
        ref
        / "mau-phieu-dieu-tra-pho-cap-giao-duc-xoa-mu-chu.xlsx"
    ).write_bytes(xlsx)


def _create_tables() -> None:
    sys.path.insert(0, str(PROJECT))
    old = Path.cwd()
    try:
        os.chdir(PROJECT)
        from app.database import Base, engine
        import app.models  # noqa: F401
        import app.survey_models  # noqa: F401
        import app.household_import_models  # noqa: F401

        Base.metadata.create_all(bind=engine)
    finally:
        os.chdir(old)
        try:
            sys.path.remove(str(PROJECT))
        except ValueError:
            pass


def _verify() -> None:
    checks = {
        "app/main.py": [
            MARK_MAIN,
            "household_updates_router",
        ],
        "app/access_control.py": [
            MARK_ACCESS + "_ACTION_START",
            MARK_ACCESS + "_SCOPE_START",
            MARK_ACCESS + "_LOCK_START",
        ],
        "app/templates/partials/dropdown_menu_v1.html": [
            MARK_MENU,
            "/dieu-tra/cap-nhat-ho-dan",
        ],
        "app/routers/survey_print.py": [
            MARK_PRINT + "_START",
            '"pages": people_pages',
            "SurveyPersonYearRecord.school_year",
        ],
        "app/templates/surveys/field_print.html": [
            "A4 landscape",
            "PHIẾU ĐIỀU TRA PHỔ CẬP GIÁO DỤC - CHỐNG MÙ CHỮ",
            "row.pages",
        ],
        "app/routers/household_updates.py": [
            "/cap-nhat-ho-dan",
            "CHO_XU_LY_XLS",
            "DUPLICATE_FILE",
        ],
        "app/household_import_models.py": [
            "class HouseholdImportJob",
            "class HouseholdImportError",
        ],
    }
    for rel, markers in checks.items():
        text_value = _read(rel)
        for marker in markers:
            if marker not in text_value:
                raise RuntimeError(
                    f"Kiểm tra sau cài không đạt: {rel} / {marker}"
                )

    python_files = [
        APP / "main.py",
        APP / "access_control.py",
        APP / "routers" / "survey_print.py",
        APP / "routers" / "household_updates.py",
        APP / "household_import_models.py",
    ]
    for path in python_files:
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(path)],
            cwd=PROJECT,
            check=True,
        )

    from jinja2 import Environment, FileSystemLoader
    env = Environment(
        loader=FileSystemLoader(str(APP / "templates"))
    )
    for name in [
        "partials/dropdown_menu_v1.html",
        "surveys/field_print.html",
        "surveys/household_update_center_v1.html",
        "surveys/household_import_detail_v1.html",
        "surveys/household_statistics_v1.html",
    ]:
        env.get_template(name)

    ref = APP / "reference" / "bai_13b_9"
    if hashlib.sha256(
        (ref / "pcgd_nhapphieudieutra_2025.xls").read_bytes()
    ).hexdigest() != XLS_SHA256:
        raise RuntimeError("Mẫu .xls sau cài bị thay đổi.")
    if hashlib.sha256(
        (
            ref
            / "mau-phieu-dieu-tra-pho-cap-giao-duc-xoa-mu-chu.xlsx"
        ).read_bytes()
    ).hexdigest() != XLSX_SHA256:
        raise RuntimeError("Mẫu phiếu .xlsx sau cài bị thay đổi.")


def _clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


